// Turns whatever the voice platform sends into one clean event.
// Supports: Vapi (tool-calls + end-of-call-report) and a plain JSON format for testing/other providers.
const req = $input.first().json;
const cfg = $('Config').first().json;
const headers = req.headers || {};
const body = req.body || {};

// ---- optional shared-secret check (set "shared_secret" in the Config node) ----
if (cfg.shared_secret) {
  const bearer = String(headers['authorization'] || '').replace(/^Bearer\s+/i, '');
  const got = headers['x-vapi-secret'] || headers['x-webhook-secret'] || bearer || '';
  if (got !== cfg.shared_secret) return [{ json: { event: 'unauthorized' } }];
}

const parseArgs = (a) => {
  if (!a) return {};
  if (typeof a === 'string') { try { return JSON.parse(a); } catch (e) { return { request: a }; } }
  return a;
};

const m = body.message;

// ------------------------------ Vapi ------------------------------
if (m && typeof m === 'object' && m.type) {
  const call = m.call || {};
  const base = {
    source: 'vapi',
    call_id: call.id || 'unknown-call',
    caller_phone: (call.customer && call.customer.number) || '',
    tool_call_id: '',
    tool_name: '',
    message: '',
  };

  if (m.type === 'tool-calls') {
    const tc = (m.toolCallList && m.toolCallList[0])
      || (m.toolWithToolCallList && m.toolWithToolCallList[0] && m.toolWithToolCallList[0].toolCall)
      || (m.toolCalls && m.toolCalls[0]);
    if (!tc) return [{ json: { ...base, event: 'ignore' } }];
    const fn = tc.function || {};
    const args = parseArgs(tc.arguments || tc.parameters || fn.arguments || fn.parameters);
    const text = String(args.request || args.message || args.query || args.text || '').trim();
    return [{ json: {
      ...base,
      event: text ? 'turn' : 'ignore',
      tool_call_id: tc.id || '',
      tool_name: tc.name || fn.name || '',
      message: text,
    } }];
  }

  if (m.type === 'end-of-call-report') {
    const art = m.artifact || {};
    let dur = m.durationSeconds ?? (m.durationMs ? Math.round(m.durationMs / 1000) : null);
    const started = m.startedAt || call.startedAt || null;
    const ended = m.endedAt || call.endedAt || null;
    if (dur == null && started && ended) dur = Math.round((new Date(ended) - new Date(started)) / 1000);
    return [{ json: {
      ...base,
      event: 'end_of_call',
      report: {
        transcript: art.transcript || m.transcript || '',
        summary: m.summary || (m.analysis && m.analysis.summary) || '',
        duration_seconds: dur,
        ended_reason: m.endedReason || '',
        recording_url: (art.recording && (art.recording.mono && art.recording.mono.combinedUrl)) || art.recordingUrl || m.recordingUrl || '',
        started_at: started,
        ended_at: ended,
      },
    } }];
  }

  return [{ json: { ...base, event: 'ignore' } }];
}

// ------------------------- Generic JSON -------------------------
const callId = String(body.call_id || body.callId || ('sim-' + Date.now()));
const phone = String(body.caller_phone || body.from || '');

if (body.event === 'end_of_call') {
  return [{ json: {
    source: 'generic', event: 'end_of_call', call_id: callId, caller_phone: phone,
    tool_call_id: '', tool_name: '', message: '',
    report: {
      transcript: String(body.transcript || ''),
      summary: String(body.summary || ''),
      duration_seconds: body.duration_seconds ?? null,
      ended_reason: String(body.ended_reason || 'customer-ended-call'),
      recording_url: String(body.recording_url || ''),
      started_at: body.started_at || null,
      ended_at: body.ended_at || null,
    },
  } }];
}

const text = String(body.message || body.text || '').trim();
return [{ json: {
  source: 'generic', event: text ? 'turn' : 'ignore', call_id: callId, caller_phone: phone,
  tool_call_id: '', tool_name: '', message: text,
} }];

// Deterministic safety net that runs BEFORE the LLM.
// Anything that must go to a human is caught here - fast, free, and not up to the model.
const item = $input.first().json;
const text = String(item.message || '').toLowerCase();

const rules = [
  { category: 'legal', priority: 'urgent', reason: 'Legal threat or legal complaint',
    re: /\b(lawyer|attorney|solicitor|sue you|suing|lawsuit|legal action|legal team|take you to court|small claims|consumer (protection|affairs)|report you to)\b/ },
  { category: 'payment', priority: 'high', reason: 'Payment problem or possible double charge',
    re: /\b(charged (me )?twice|double[- ]?charged?|charged two times|overcharged|unauthori[sz]ed (charge|transaction|payment)|charge ?back|dispute (the|a|this) (charge|payment|transaction)|fraud(ulent)?|payment (failed|declined|problem|issue|error))\b/ },
  { category: 'refund', priority: 'high', reason: 'Refund dispute',
    re: /\b(refund dispute|want my money back|demand (a )?refund|where('?s| is) my refund|refund (was|has been) (denied|refused)|never (got|received) (my|the|a) refund)\b/ },
  { category: 'human_request', priority: 'normal', reason: 'Customer explicitly asked for a human',
    re: /\b(real person|live (agent|person)|human|actual person|(speak|talk|transfer|connect|put|get)( me)?( (to|with|through))? (a |an |the |your )?(person|agent|representative|rep|manager|supervisor|someone|somebody|operator|staff|receptionist))\b/ },
  { category: 'complaint', priority: 'high', reason: 'Customer sounds angry or abusive',
    re: /\b(furious|livid|outraged|unacceptable|this is a scam|worst (service|hotel|company|experience)|fed up|sick of|fuck\w*|shit\w*|idiots?|useless)\b/ },
];

const hit = rules.find(r => r.re.test(text));
return [{ json: {
  ...item,
  force_escalation: !!hit,
  forced_category: hit ? hit.category : '',
  forced_priority: hit ? hit.priority : '',
  forced_reason: hit ? hit.reason : '',
} }];

