// Merges the AI's structured answer with hard guardrails and produces ONE final decision.
const norm = $('Normalize Event').first().json;
const pre = $('Rules Pre-Check').first().json;
const input = $input.first().json;
const msg = norm.message || '';

const HANDOFF = 'I understand, and I want to make sure this is handled properly. I am passing your details to a member of our team right now so you will not have to repeat yourself, and they will follow up with you shortly.';
const FALLBACK = 'I am sorry, I am having a little trouble with that. Let me pass this to a member of our team who can help you, and they will follow up with you shortly.';

const base = {
  reply: '', intent: 'other', sentiment: 'neutral', escalate: false, escalation_reason: '',
  priority: 'normal', summary: '', customer_name: '', booking_number: '', requested_action: '',
  relevant_info: '', suggested_action: '', resolved: false,
};

let d;
if (pre.force_escalation) {
  d = { ...base, reply: HANDOFF, intent: pre.forced_category, sentiment: 'negative', escalate: true,
        escalation_reason: pre.forced_reason, priority: pre.forced_priority,
        summary: 'Customer said: "' + msg + '"', suggested_action: 'Call the customer back and review the case.',
        decided_by: 'rules' };
} else {
  let out = input.output;
  if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = null; } }
  if (!out || typeof out !== 'object' || input.error) {
    d = { ...base, reply: FALLBACK, escalate: true, escalation_reason: 'AI agent error or invalid output',
          summary: 'Customer said: "' + msg + '"', suggested_action: 'Review the call and follow up manually.',
          decided_by: 'fallback' };
  } else {
    d = { ...base, ...out, decided_by: 'ai' };
  }
}
// Save the booking number from the caller's own words when the AI didn't (e.g. on the fast rules path)
if (!d.booking_number) {
  const found = (msg.match(/\b([A-Z]{2,3})-?(\d{4,})\b/i) || []);
  if (found[0]) d.booking_number = found[1].toUpperCase() + '-' + found[2];
}
// ---- guardrails ----
if (!d.escalate && d.sentiment === 'negative' && ['refund', 'payment', 'legal', 'complaint'].includes(d.intent)) {
  d.escalate = true;
  d.escalation_reason = d.escalation_reason || 'Negative sentiment on a sensitive topic';
  d.decided_by += '+guardrail';
}
if (d.escalate) {
  d.resolved = false;
  if (!d.priority || d.priority === 'low') d.priority = 'normal';
  if (['legal', 'payment'].includes(d.intent) && !['high', 'urgent'].includes(d.priority)) d.priority = 'high';
  if (!/(team|colleague|member|human|follow up|call you back|reach out)/i.test(d.reply)) {
    d.reply = (d.reply + ' I will pass this to a member of our team, and they will follow up with you shortly.').trim();
  }
}
d.reply = String(d.reply || '').replace(/[*_#`>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 700);
if (!d.reply) d.reply = 'Sorry, could you please repeat that?';
if (!d.summary) d.summary = 'Customer said: "' + msg + '"';

return [{ json: d }];

// Adds the ticket reference to what the customer will hear.
const d = $('Decision Engine').first().json;
const t = $input.first().json || {};
const num = String(t.ticket_number || '').replace(/\D/g, '');
let reply = d.reply;
if (t.is_new && num) reply += ' Your reference number is ' + num + '.';
return [{ json: { ...d, reply,
  ticket_number: t.ticket_number || '', ticket_id: t.id || null,
  is_new_ticket: !!t.is_new, ticket_transcript: t.transcript || '' } }];

// Formats the reply in the shape the voice platform expects.
const d = $input.first().json;
const n = $('Normalize Event').first().json;
let http_response;
if (n.source === 'vapi') {
  // Vapi: results[].result must be a single-line string; the assistant reads it to the caller.
  http_response = { results: [{ name: n.tool_name || undefined, toolCallId: n.tool_call_id, result: d.reply }] };
} else {
  http_response = { reply: d.reply, escalated: !!d.escalate, intent: d.intent, sentiment: d.sentiment,
                    ticket: d.ticket_number || null, call_id: n.call_id };
}
return [{ json: { ...d, http_response, notify_team: !!(d.escalate && d.is_new_ticket) } }];

// Builds the "Human assistance required" Slack card (Block Kit) for the support team.
const d = $('Build Voice Response').first().json;
const n = $('Normalize Event').first().json;

// Link for the "Open dashboard" button. Change it if your n8n address changes.
const DASHBOARD_URL = 'https://<your-n8n>/webhook/voice-dashboard?days=7';

const clip = (s, max) => { s = String(s == null ? '' : s).trim(); return s.length > max ? s.slice(0, max - 1) + '…' : s; };
const cap = (s) => { s = String(s || '').replace(/_/g, ' ').trim(); return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; };
// On the fast rules path the AI never ran, so read the booking number and last name from what the caller said
const said = String(n.message || '') + ' ' + String(d.summary || '');
const bookingFound = (said.match(/\b[A-Z]{2,3}-?\d{4,}\b/i) || [])[0] || '';
const lastNameFound = (said.match(/last name (?:is )?([A-Z][a-zA-Z'-]+)/i) || [])[1] || '';
const booking = d.booking_number || (bookingFound ? bookingFound.toUpperCase() : '');
const guest = d.customer_name || (lastNameFound ? 'Guest ' + cap(lastNameFound) : '');
const pr = String(d.priority || 'normal').toLowerCase();
const icon = { urgent: ':rotating_light:', high: ':red_circle:', normal: ':large_orange_circle:', low: ':large_yellow_circle:' }[pr] || ':red_circle:';
const prLabel = pr.charAt(0).toUpperCase() + pr.slice(1);
const ticket = d.ticket_number || 'No ticket';
const customer = (guest || 'Unknown caller') + (n.caller_phone ? '  ·  ' + n.caller_phone : '');
const transcript = String(d.ticket_transcript || '').split('\n').slice(-12).join('\n');

const blocks = [
  { type: 'header', text: { type: 'plain_text', emoji: true, text: clip('Human assistance needed · ' + ticket, 150) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: icon + ' *' + prLabel + ' priority*  ·  ' + clip(d.escalation_reason || 'Escalated by the AI agent', 200) }] },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Customer*\n' + clip(customer, 300) },
    { type: 'mrkdwn', text: '*Booking*\n' + clip(booking || 'Not given', 100) },
    { type: 'mrkdwn', text: '*Reason*\n' + clip(cap(d.intent || 'other'), 100) },
    { type: 'mrkdwn', text: '*Sentiment*\n' + ({ positive: ':slightly_smiling_face: ', neutral: ':neutral_face: ', negative: ':disappointed: ' }[d.sentiment] || '') + clip(cap(d.sentiment || 'neutral'), 50) },
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: '*Summary*\n' + clip(d.summary || 'n/a', 1500) } },
];
if (d.relevant_info) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*What the AI found*\n' + clip(d.relevant_info, 1500) } });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Suggested action*\n' + clip(d.suggested_action || 'Review the case and follow up with the customer.', 1000) } });
if (transcript) {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Latest turns*\n```' + clip(transcript, 2700) + '```' } });
}
// a plain link, not a button: buttons show a warning unless the Slack app has an interactivity endpoint
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':bar_chart: <' + DASHBOARD_URL + '|Open the live dashboard>  ·  Sent by the AI voice agent · the caller was told a person will follow up' }] });

// text = the notification preview on phones and in the sidebar
const text = icon + ' ' + prLabel + ' · ' + ticket + ' · ' + clip(guest || n.caller_phone || 'Unknown caller', 60) + ': ' + clip(d.escalation_reason || 'needs a person', 120);
return [{ json: { text, blocks: JSON.stringify({ blocks }) } }];

// Combines the voice platform's end-of-call report with what we logged ourselves.
const norm = $('Normalize Event').first().json;
const db = $input.first().json;
const rep = norm.report || {};
const transcript = (rep.transcript && String(rep.transcript).trim()) ? String(rep.transcript).trim() : (db.turns_transcript || '');

let dur = rep.duration_seconds;
if (dur == null && rep.started_at && rep.ended_at) dur = Math.round((new Date(rep.ended_at) - new Date(rep.started_at)) / 1000);
if (dur == null && db.first_turn && db.last_turn) dur = Math.round((new Date(db.last_turn) - new Date(db.first_turn)) / 1000);

return [{ json: {
  call_id: norm.call_id,
  caller_phone: norm.caller_phone || db.caller_phone || '',
  transcript: (transcript || '(no transcript available)').slice(0, 12000),
  duration_seconds: dur == null ? 0 : dur,
  ended_reason: rep.ended_reason || '',
  recording_url: rep.recording_url || '',
  started_at: rep.started_at || db.started_at || '',
  vendor_summary: rep.summary || '',
  escalated: !!db.was_escalated,
  ticket_number: db.ticket_number || '',
  customer_email: db.customer_email || '',
  customer_name: db.resolved_name || '',
  booking_number: db.booking_number || '',
  last_intent: db.primary_intent || '',
} }];

