// Turns the AI analysis into the final metrics row (resolution time, outcome flags, follow-up decision).
const inp = $('Prepare Analysis Input').first().json;
const cfg = $('Config').first().json;

let a = $input.first().json || {};
a = a.output ?? a.text ?? a.response ?? a;
if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = {}; } }
if (a && typeof a.output === 'object') a = a.output;
a = a || {};

const sentiments = ['positive', 'neutral', 'negative'];
const escalated = !!inp.escalated || !!a.human_escalation;
const resolved = !escalated && !!a.resolved_by_ai;
const dur = Math.max(0, Math.round(Number(inp.duration_seconds) || 0));
const fmt = (s) => Math.floor(s / 60) + 'm ' + String(s % 60).padStart(2, '0') + 's';
const followUp = !!a.follow_up_required || escalated;
const email = inp.customer_email || '';
const body = String(a.follow_up_email_body || '').trim();

return [{ json: {
  call_id: inp.call_id,
  caller_phone: inp.caller_phone,
  customer_name: a.customer_name || inp.customer_name || '',
  booking_number: a.booking_number || inp.booking_number || '',
  started_at: inp.started_at || '',
  duration_seconds: dur,
  resolution_time: fmt(dur),
  ended_reason: inp.ended_reason,
  call_reason: a.call_reason || 'Unknown',
  primary_intent: a.primary_intent || inp.last_intent || 'other',
  sentiment: sentiments.includes(a.sentiment) ? a.sentiment : 'neutral',
  customer_satisfaction: Math.min(5, Math.max(0, parseInt(a.customer_satisfaction) || 0)),
  resolved_by_ai: resolved,
  escalated,
  ticket_number: inp.ticket_number,
  follow_up_required: followUp,
  follow_up_reason: a.follow_up_reason || (escalated ? 'Escalated to the human team' : ''),
  summary: a.summary || inp.vendor_summary || '',
  transcript: inp.transcript,
  recording_url: inp.recording_url,
  customer_email: email,
  follow_up_email_subject: a.follow_up_email_subject || ('Following up on your call to ' + cfg.business_name),
  follow_up_email_body: body,
  send_email: !!(cfg.send_followup_emails && followUp && email && body),
} }];

// AI Voice Agent dashboard: one static HTML page.
// n8n serves webhook pages without JavaScript, so tiles, the compare switch and the period tabs are plain links
// (?days=30&metric=ai&compare=1) and every tooltip is CSS-only.
//
// Deviation from the dashboard-design skill (noted on purpose): each KPI tile keeps one short muted sub-line,
// because the owner asked for this reference layout.

// ---------- settings (edit these) ----------
const BUSINESS = 'Grand Palm Hotel';
const HUMAN_MINUTES_PER_CALL = 6;   // estimate: staff time one call would take a person
const STAFF_COST_PER_HOUR = 15;     // estimate: loaded hourly cost of a support agent
const CURRENCY = '$';
// -------------------------------------------

const k = ($input.first().json || {}).kpi || {};
let q = {};
try { q = $('Dashboard Webhook').first().json.query || {}; } catch (e) { q = {}; }

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const num = (v) => Number(v) || 0;
const int = (n) => Math.round(num(n)).toLocaleString('en-US');
const pctOf = (n, d) => (d ? (n / d) * 100 : 0);
const dur = (s) => { const t = Math.round(num(s)); return t >= 60 ? Math.floor(t / 60) + 'm ' + String(t % 60).padStart(2, '0') + 's' : t + 's'; };
const nice = (s) => (s === 'faq' ? 'FAQ' : String(s || 'other').replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase()));
const DASH = '&mdash;';

const days = num(k.days) || 30;
const unit = k.unit === 'week' ? 'week' : 'day';
const compare = q.compare !== '0';
const total = num(k.calls_received);
const ai = num(k.ai_resolved);
const escN = num(k.human_escalated);
const prev = k.prev || {};
const prevTotal = num(prev.calls_received);
const live = num(k.live_calls);
const hrs = (n) => (n * HUMAN_MINUTES_PER_CALL) / 60;

const series = (k.series || []).map((s) => ({ label: s.label, total: num(s.total), ai: num(s.ai), esc: num(s.esc), avg_dur: num(s.avg_dur), prev: s.prev || {} }));

// ---- metrics: one definition drives the tile, its sparkline and the main chart ----
const METRICS = {
  calls: { label: 'Calls handled', fmt: int, axis: (v) => int(v), good: null, rate: false,
           value: total, before: prevTotal,
           sub: total ? int(k.follow_ups) + ' needed a follow-up' : 'No calls yet',
           point: (s) => num(s.total) },
  ai:    { label: 'Resolved by AI', fmt: (v) => Math.round(v) + '%', axis: (v) => v + '%', good: true, rate: true, max: 100,
           value: pctOf(ai, total), before: prevTotal ? pctOf(num(prev.ai_resolved), prevTotal) : null,
           sub: total ? int(ai) + ' of ' + int(total) + ' calls, no human' : 'No calls yet',
           point: (s) => pctOf(num(s.ai), num(s.total)), hasPoint: (s) => num(s.total) > 0 },
  esc:   { label: 'Escalated', fmt: (v) => Math.round(v) + '%', axis: (v) => v + '%', good: false, rate: true, max: 100,
           value: pctOf(escN, total), before: prevTotal ? pctOf(num(prev.human_escalated), prevTotal) : null,
           sub: total ? int(escN) + ' handed to a person' : 'No calls yet',
           point: (s) => pctOf(num(s.esc), num(s.total)), hasPoint: (s) => num(s.total) > 0 },
  aht:   { label: 'Avg handling time', fmt: dur, axis: (v) => (v >= 60 ? Math.round(v / 60) + 'm' : v + 's'), good: false, rate: false,
           value: num(k.avg_handle_seconds), before: prevTotal ? num(prev.avg_handle_seconds) : null,
           sub: total ? 'per completed call' : 'No calls yet',
           point: (s) => num(s.avg_dur), hasPoint: (s) => num(s.total) > 0 },
  saved: { label: 'Staff time saved', fmt: (v) => v.toFixed(1) + ' hrs', axis: (v) => v + 'h', good: true, rate: false, est: true,
           value: hrs(ai), before: prevTotal ? hrs(num(prev.ai_resolved)) : null,
           sub: total ? '&asymp; ' + CURRENCY + int(hrs(ai) * STAFF_COST_PER_HOUR) + ' at ' + CURRENCY + STAFF_COST_PER_HOUR + '/hr' : 'No calls yet',
           point: (s) => hrs(num(s.ai)) },
};
const metricKey = METRICS[q.metric] ? q.metric : 'ai';
const M = METRICS[metricKey];

const href = (o) => {
  const p = Object.assign({ days, metric: metricKey, compare: compare ? 1 : 0 }, o);
  return '?days=' + p.days + '&amp;metric=' + p.metric + (p.compare ? '' : '&amp;compare=0');
};

// ---- change vs the previous period (same elapsed time) ----
function delta(m) {
  if (!total || m.before == null) return '';
  if (prevTotal < 5) return '<span class="d n" title="Previous ' + days + ' days">was ' + m.fmt(m.before) + '</span>';
  let diff, text;
  if (m.rate) { diff = Math.round(m.value - m.before); text = Math.abs(diff) + (Math.abs(diff) === 1 ? ' pt' : ' pts'); }
  else { if (!m.before) return ''; diff = Math.round(((m.value - m.before) / m.before) * 100); text = Math.abs(diff) > 999 ? '10&times;' : Math.abs(diff) + '%'; }
  const title = ' title="Previous ' + days + ' days: ' + m.fmt(m.before) + '"';
  if (diff === 0) return '<span class="d n"' + title + '>&plusmn;0%</span>';
  const cls = m.good == null ? 'n' : ((diff > 0) === m.good ? 'up' : 'down');
  return '<span class="d ' + cls + '"' + title + '>' + (diff > 0 ? '+' : '&minus;') + text + '</span>';
}

// ---- smooth line (monotone cubic: never overshoots below zero) ----
function tangents(pts) {
  const n = pts.length, m = new Array(n).fill(0);
  if (n < 2) return m;
  const d = [];
  for (let i = 0; i < n - 1; i++) d.push((pts[i + 1][1] - pts[i][1]) / (pts[i + 1][0] - pts[i][0]));
  m[0] = d[0]; m[n - 1] = d[n - 2];
  for (let i = 1; i < n - 1; i++) m[i] = d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2;
  for (let i = 0; i < n - 1; i++) {
    if (d[i] === 0) { m[i] = 0; m[i + 1] = 0; continue; }
    const a = m[i] / d[i], b = m[i + 1] / d[i], h = a * a + b * b;
    if (h > 9) { const t = 3 / Math.sqrt(h); m[i] = t * a * d[i]; m[i + 1] = t * b * d[i]; }
  }
  return m;
}
function curve(pts, from, to) {
  if (pts.length < 2) return '';
  const m = tangents(pts);
  let p = 'M' + pts[from][0].toFixed(2) + ',' + pts[from][1].toFixed(2);
  for (let i = from; i < to; i++) {
    const [x0, y0] = pts[i], [x1, y1] = pts[i + 1], dx = (x1 - x0) / 3;
    p += 'C' + (x0 + dx).toFixed(2) + ',' + (y0 + m[i] * dx).toFixed(2) + ' ' + (x1 - dx).toFixed(2) + ',' + (y1 - m[i + 1] * dx).toFixed(2) + ' ' + x1.toFixed(2) + ',' + y1.toFixed(2);
  }
  return p;
}
function niceTicks(max, count) {
  if (!(max > 0)) return [0, 1, 2, 3, 4];
  const raw = max / count, pow = Math.pow(10, Math.floor(Math.log10(raw)));
  const step = [1, 2, 2.5, 5, 10].map((x) => x * pow).find((s) => s >= raw);
  const out = [];
  for (let i = 0; i * step < max + step * 0.999; i++) out.push(+(i * step).toFixed(6));
  return out;
}

// ---- sparkline for a tile ----
function spark(m, on) {
  const n = series.length, W = 100, H = 28;
  const idx = series.map((s, i) => i).filter((i) => !m.hasPoint || m.hasPoint(series[i]));
  if (n < 2 || idx.length < 2 || !total) return '<div class="spark"></div>';
  const vals = idx.map((i) => m.point(series[i]));
  const max = m.max || Math.max(1, ...vals);
  const pts = idx.map((i, j) => [(i / (n - 1)) * W, H - 1 - (vals[j] / max) * (H - 3)]);
  const line = curve(pts, 0, pts.length - 1);
  return '<svg class="spark' + (on ? ' on' : '') + '" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" aria-hidden="true">' +
    '<path class="sf" d="' + line + 'L' + pts[pts.length - 1][0] + ',' + H + 'L' + pts[0][0] + ',' + H + 'Z"/><path class="sl" d="' + line + '"/></svg>';
}

// ---- KPI strip ----
const tiles = Object.entries(METRICS).map(([key, m]) => {
  const on = key === metricKey;
  return '<a class="tile' + (on ? ' on' : '') + '" href="' + href({ metric: key }) + '"' + (on ? ' aria-current="true"' : '') + '><div class="tin">' +
    '<div class="th"><span>' + m.label + (m.est ? ' <span class="est" title="Estimate: ' + HUMAN_MINUTES_PER_CALL + ' min of staff time per AI-resolved call. Change it at the top of the Build Dashboard HTML node.">est.</span>' : '') + '</span>' + delta(m) + '</div>' +
    '<div class="tv">' + (total ? m.fmt(m.value) : DASH) + '</div>' +
    '<div class="ts">' + m.sub + '</div>' + spark(m, on) + '</div></a>';
}).join('');

// ---- main chart ----
function mainChart() {
  const n = series.length;
  if (!n || !total) return '<div class="nochart">No completed calls in the last ' + days + ' days yet.</div>';
  const cur = series.map((s) => (M.hasPoint && !M.hasPoint(s) ? null : M.point(s)));
  const pre = series.map((s) => (M.hasPoint && !M.hasPoint(s.prev) ? null : M.point(s.prev)));
  const all = cur.concat(compare ? pre : []).filter((v) => v != null);
  const ticks = M.max ? [0, 25, 50, 75, 100] : niceTicks(Math.max(...all, 0), 4);
  const top = ticks[ticks.length - 1] || 1;
  const W = 1000, H = 240, X = (i) => (n === 1 ? W / 2 : (i / (n - 1)) * W), Y = (v) => H - (v / top) * H;
  // a day with no calls has no rate: the line skips it instead of dropping to 0%
  const toPts = (arr) => arr.map((v, i) => (v == null ? null : [X(i), Y(v)])).filter(Boolean);
  const cp = toPts(cur), pp = toPts(pre);
  const c = cp.length;
  const lastIsToday = cur[n - 1] != null;            // today is unfinished: its segment is dashed
  const curLine = curve(cp, 0, lastIsToday ? c - 2 : c - 1), tail = lastIsToday && c > 1 ? curve(cp, c - 2, c - 1) : '';
  const full = curve(cp, 0, c - 1);
  const prevLine = curve(pp, 0, pp.length - 1);
  const base = (pts) => (pts.length ? 'L' + pts[pts.length - 1][0] + ',' + H + 'L' + pts[0][0] + ',' + H + 'Z' : '');
  const svg = '<svg class="plot" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" aria-hidden="true">' +
    ticks.map((t) => '<line class="grid" x1="0" x2="' + W + '" y1="' + Y(t) + '" y2="' + Y(t) + '"/>').join('') +
    (compare && pp.length > 1 ? '<path class="pf" d="' + prevLine + base(pp) + '"/><path class="pl" d="' + prevLine + '"/>' : '') +
    (c > 1 ? '<path class="cf" d="' + full + base(cp) + '"/>' : '') +
    '<path class="cl" d="' + curLine + '"/>' + (tail ? '<path class="cl tail" d="' + tail + '"/>' : '') + '</svg>';
  const yAxis = ticks.map((t) => '<span style="bottom:' + (t / top) * 100 + '%">' + M.axis(t) + '</span>').join('');
  const every = Math.max(1, Math.ceil(n / 7));
  const xAxis = series.map((s, i) => ((n - 1 - i) % every === 0 ? '<span style="left:' + (n === 1 ? 50 : (i / (n - 1)) * 100) + '%">' + esc(s.label) + '</span>' : '')).join('');
  const colW = n === 1 ? 100 : 100 / (n - 1);
  const hits = series.map((s, i) => {
    const left = n === 1 ? 50 : (i / (n - 1)) * 100;
    const edge = i < 3 ? ' l' : (i > n - 4 ? ' r' : '');
    const v = cur[i], pv = pre[i];
    const partial = i === n - 1 ? ' so far' : '';
    return '<div class="hit' + edge + '" tabindex="0" style="left:' + left + '%;width:' + colW + '%">' +
      '<i class="hair"></i>' +
      (v != null ? '<i class="dot" style="bottom:' + (v / top) * 100 + '%"></i>' : '') +
      (compare && pv != null ? '<i class="dot pd" style="bottom:' + (pv / top) * 100 + '%"></i>' : '') +
      '<span class="tip"><b>' + (v != null ? M.fmt(v) : DASH) + '</b>' +
      '<span class="tl">' + (unit === 'week' ? 'Week of ' : '') + esc(s.label) + partial + ' &middot; ' + int(s.total) + (s.total === 1 ? ' call' : ' calls') + '</span>' +
      (compare ? '<span class="tl"><i class="key pk"></i>Period before: ' + (pv != null ? M.fmt(pv) : DASH) + '</span>' : '') + '</span></div>';
  }).join('');
  return '<div class="chart"><div class="yax">' + yAxis + '</div><div class="area">' + svg + '<div class="hits">' + hits + '</div><div class="xax">' + xAxis + '</div></div></div>';
}

// ---- ranked lists ----
function ranked(title, cols, rows, foot) {
  const max = Math.max(1, ...rows.map((r) => r.bar));
  const body = rows.length ? rows.map((r) =>
    '<div class="row"><span class="rn">' + (r.icon || '') + '<span class="nm">' + r.name + '</span></span>' +
    r.cells.map((c) => '<span class="rc">' + c + '</span>').join('') +
    '<span class="track"><span class="fill' + (r.warm ? ' warm' : '') + '" style="width:' + Math.max(1.5, (r.bar / max) * 100) + '%"></span></span></div>').join('')
    : '<div class="none">Nothing here yet</div>';
  return '<section class="card list"><h2>' + title + '</h2><div class="lh"><span>' + cols[0] + '</span>' + cols.slice(1).map((c) => '<span class="rc">' + c + '</span>').join('') + '</div>' +
    body + (foot ? '<p class="foot">' + foot + '</p>' : '') + '</section>';
}
const intents = k.by_intent || [];
const reasons = ranked('Why customers call', ['Reason', 'Calls', 'AI handled'],
  intents.map((i) => ({ name: esc(nice(i.intent)), bar: num(i.calls), cells: [int(i.calls), Math.round(pctOf(num(i.ai), num(i.calls))) + '%'] })),
  total ? 'All ' + int(total) + ' calls scored by the post-call AI' : '');
const sentCount = (s) => { const r = (k.by_sentiment || []).find((x) => x.sentiment === s); return r ? num(r.calls) : 0; };
const sentTotal = ['positive', 'neutral', 'negative'].reduce((a, s) => a + sentCount(s), 0);
const csat = k.avg_csat != null ? Number(k.avg_csat) : null;
const sentiment = ranked('How callers felt', ['Sentiment', 'Calls', 'Share'],
  sentTotal ? [['positive', '&#9650;', 'pos'], ['neutral', '&#9679;', 'neu'], ['negative', '&#9660;', 'neg']].map(([s, icon, c]) => ({
    name: nice(s), icon: '<span class="ic ' + c + '">' + icon + '</span>', bar: sentCount(s), warm: s === 'negative',
    cells: [int(sentCount(s)), Math.round(pctOf(sentCount(s), sentTotal)) + '%'] })) : [],
  csat != null ? 'Avg satisfaction <b>' + csat.toFixed(1) + ' / 5</b> &middot; AI estimate from the transcript' : '');
const prioCount = (p) => { const r = (k.tickets_by_priority || []).find((x) => x.priority === p); return r ? num(r.n) : 0; };
const openTickets = num(k.open_tickets);
const tickets = ranked('Open tickets', ['Priority', 'Tickets', ''],
  openTickets ? [['urgent', '&#9888;'], ['high', '&#9650;'], ['normal', '&#9679;'], ['low', '&#9661;']].map(([p, icon]) => ({
    name: nice(p), icon: '<span class="ic p-' + p + (prioCount(p) ? ' has' : '') + '">' + icon + '</span>', bar: prioCount(p), warm: p === 'urgent' || p === 'high',
    cells: [int(prioCount(p)), ''] })) : [],
  openTickets ? int(openTickets) + ' waiting for a person' : '');

// ---- recent calls ----
const recent = (k.recent || []).map((r) => {
  const outcome = r.escalated ? '<span class="pill esc">&#8599; Human' + (r.ticket ? ' &middot; ' + esc(r.ticket) : '') + '</span>'
    : r.resolved_by_ai ? '<span class="pill ok">&#10003; AI resolved</span>' : '<span class="pill un">&#9675; Unresolved</span>';
  const s = { positive: '<span class="ic pos">&#9650;</span>', negative: '<span class="ic neg">&#9660;</span>' }[r.sentiment] || '<span class="ic neu">&#9679;</span>';
  return '<tr><td class="mut nw">' + esc(r.at) + '</td><td>' + (r.name ? esc(r.name) + '<div class="mut sm">' + esc(r.phone) + '</div>' : esc(r.phone)) + '</td>' +
    '<td>' + esc(r.reason) + '</td><td class="nw">' + s + ' ' + esc(nice(r.sentiment)) + '</td><td>' + outcome + '</td><td class="r tn">' + dur(r.duration_seconds) + '</td></tr>';
}).join('');

