.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:20px}
.list{padding:18px 20px 16px}
.stack{display:flex;flex-direction:column;gap:20px}.stack .list:last-child{flex:1}
h2{font-size:15px;font-weight:600;margin:0 0 14px;letter-spacing:-.005em}
.lh,.row{display:grid;grid-template-columns:1fr 84px 84px;align-items:center;gap:8px}
.lh{font-size:12px;color:var(--muted);padding:0 4px 6px}
.row{position:relative;height:44px;padding:0 4px 6px;font-size:14px;border-radius:10px}
.row:hover{background:var(--soft)}
.rn{display:flex;align-items:center;gap:9px;min-width:0}
.nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rc{text-align:right;font-variant-numeric:tabular-nums;color:var(--ink)}
.lh .rc{color:var(--muted)}
.track{position:absolute;left:4px;right:4px;bottom:5px;height:3px;border-radius:999px;background:var(--line);overflow:hidden}
.fill{position:absolute;left:0;top:0;bottom:0;border-radius:999px;background:var(--accent);opacity:.8}
.row:hover .fill{opacity:1}
.fill.warm{background:var(--warm)}
.foot{font-size:12px;color:var(--muted);margin:12px 4px 0}
.foot b{color:var(--ink);font-weight:600}
.none{font-size:13px;color:var(--muted);padding:14px 4px}
.ic{width:14px;text-align:center;font-size:11px;flex:none}
.ic.pos{color:var(--accent-ink)} .ic.neu{color:var(--prev)} .ic.neg{color:var(--down)}
.ic.p-urgent.has{color:var(--down)} .ic.p-high{color:var(--warm)} .ic.p-normal,.ic.p-low,.ic.p-urgent{color:var(--prev)}

/* recent */
.recent{padding:18px 20px 8px}
.scroll{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:13.5px}
th{text-align:left;font-size:12px;font-weight:500;color:var(--muted);padding:0 10px 8px;border-bottom:1px solid var(--line)}
th.r{text-align:right}
td{padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top;color:var(--ink)}
tr:last-child td{border-bottom:0}
tbody tr:hover td{background:var(--soft)}
.pill{display:inline-block;white-space:nowrap;font-size:12px;font-weight:550;padding:2px 9px;border-radius:999px}
.pill.ok{color:var(--accent-ink);background:color-mix(in srgb,var(--accent) 12%,transparent)}
.pill.esc{color:var(--warm);background:color-mix(in srgb,var(--warm) 13%,transparent)}
.pill.un{color:var(--muted);background:var(--soft)}

@media (max-width:1000px){.kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.tile:nth-child(3){border-right:0}.tile:nth-child(-n+3){border-bottom:1px solid var(--line)}.grid2{grid-template-columns:1fr}}
@media (max-width:560px){.wrap{padding:16px 16px 40px}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.xax span:nth-child(even):not(:last-child),.xax span:nth-last-child(2){display:none}.th{font-size:13px}.tile{border-bottom:1px solid var(--line)}
  .tile:nth-child(3){border-right:1px solid var(--line)}.tile:nth-child(2n){border-right:0}.tile:last-child{grid-column:1/-1;border-bottom:0}
  .tv{font-size:24px}.chart{height:210px;grid-template-columns:36px 1fr}.lh,.row{grid-template-columns:1fr 64px 64px}.bar{flex-wrap:wrap}}
`;

const periods = [7, 30, 90].map((d) => '<a href="' + href({ days: d }) + '"' + (d === days ? ' class="on" aria-current="page"' : '') + '>' + d + ' days</a>').join('');

const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
'<meta http-equiv="refresh" content="60"><title>' + esc(BUSINESS) + ' &middot; AI Voice Agent</title><style>' + css + '</style></head><body><div class="wrap">' +

'<header class="top"><div class="brand">' + esc(BUSINESS) + '<b>AI Voice Agent</b></div>' +
  '<div class="meta"><span class="live' + (live ? ' on' : '') + '"><span class="dotl"></span>' + (live ? live + (live === 1 ? ' call' : ' calls') + ' live' : 'No live calls') + '</span>' +
  '<span title="This page reloads every 60 seconds">Updated ' + esc(k.generated_at || '') + '</span></div></header>' +

'<section class="card main">' +
  '<div class="bar"><nav class="seg" aria-label="Period">' + periods + '</nav></div>' +
  '<div class="kpis">' + tiles + '</div>' +
  '<div class="chartwrap">' +
    '<div class="ctop"><a class="switch' + (compare ? ' on' : '') + '" href="' + href({ compare: compare ? 0 : 1 }) + '" role="switch" aria-checked="' + compare + '"><span class="sw"></span>Compare with the period before</a>' +
    '<span class="ctitle">' + M.label + ' per ' + unit + '</span></div>' +
    '<div class="legend"><span><i class="key"></i>This period</span>' + (compare ? '<span><i class="key pk"></i>Period before</span>' : '') + '</div>' +
    mainChart() +
  '</div>' +
'</section>' +

'<div class="grid2">' + reasons + '<div class="stack">' + sentiment + tickets + '</div></div>' +

'<section class="card recent"><h2>Recent calls</h2><div class="scroll"><table><thead><tr><th>When</th><th>Caller</th><th>Reason</th><th>Sentiment</th><th>Outcome</th><th class="r">Duration</th></tr></thead><tbody>' +
  (recent || '<tr><td colspan="6" class="mut">Calls appear here after the first one ends.</td></tr>') + '</tbody></table></div></section>' +
'</div></body></html>';

return [{ json: { html } }];

// Builds the branded follow-up email (HTML) from the post-call analysis.
// Put this Code node between "Send Follow-up? (true)" and the Gmail node.

// ---------- settings (edit these) ----------
const HOTEL = {
  name: 'Grand Palm Hotel',
  tagline: 'Guest Care',
  phone: '+1 (555) 010-2030',
  email: 'you@example.com',
  address: '1 Palm Avenue, Miami Beach, FL',
  website: 'https://example.com',
  responseTime: 'within 24 hours',
  timeZone: 'Asia/Manila',   // time zone for the call time shown in the email
  accent: '#0f5c4d',     // deep palm green
  accentSoft: '#e8f2ef',
  gold: '#b8935a',
};
// -------------------------------------------

const m = $('Compute Call Metrics').first().json;
let loaded = {};
try { loaded = $('Load Call Data').first().json || {}; } catch (e) {}

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const title = (s) => String(s || '').trim().toLowerCase().replace(/\b[a-z]/g, (c) => c.toUpperCase());

// Guest name: AI analysis first, then the booking record
const fullName = title(loaded.resolved_name || m.customer_name || '');
const firstName = fullName.split(' ')[0] || '';
const greeting = fullName ? 'Dear ' + esc(fullName) + ',' : 'Dear Guest,';

// The AI writes its own greeting and sign-off; keep only the message in between
let body = String(m.follow_up_email_body || '').replace(/\r/g, '').trim();
// works whether the AI used line breaks or wrote everything on one line
body = body.replace(/^(dear|hi|hello|good (morning|afternoon|evening))\b[^,\n]{0,60}[,\n]\s*/i, '');
body = body.replace(/[\s,.]*\b(best|kind|warm|warmest)\s+(regards|wishes)\b[\s\S]*$/i, '');
body = body.replace(/[\s,.]*\b(sincerely|cheers|yours truly)\b,?[\s\S]{0,120}$/i, '');
body = body.trim();
if (body) body = body.charAt(0).toUpperCase() + body.slice(1);   // "we have..." -> "We have..."
if (body && !/[.!?]$/.test(body)) body += '.';                    // keep the final full stop
// keep booking / ticket numbers like HB-12345 on one line
const nowrap = (h) => h.replace(/\b([A-Z]{2,4}-\d{3,})\b/g, '<span style="white-space:nowrap;">$1</span>');
const paragraphs = body.split(/\n\s*\n/).map((p) => p.replace(/\n/g, ' ').trim()).filter(Boolean);
const bodyHtml = (paragraphs.length ? paragraphs : ['Thank you for calling us today. We are following up on your request.'])
  .map((p) => '<p style="margin:0 0 16px;font-size:15px;line-height:1.65;color:#2b2b2b;">' + nowrap(esc(p)) + '</p>').join('');

// Reference details
const ticket = m.ticket_number || '';
const booking = m.booking_number || loaded.booking_number || '';
const when = (() => {
  const d = new Date(m.started_at || Date.now());
  return isNaN(d) ? '' : d.toLocaleString('en-US', { month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: HOTEL.timeZone });
})();
const row = (label, value) => value ? (
  '<tr><td style="padding:6px 0;font-size:13px;color:#6b6b6b;width:42%;">' + label + '</td>' +
  '<td style="padding:6px 0;font-size:14px;color:#1a1a1a;font-weight:600;text-align:right;">' + esc(value) + '</td></tr>') : '';
const details = row('Reference number', ticket) + row('Booking', booking) + row('Your call', when) + row('Topic', m.call_reason && m.call_reason !== 'Unknown' ? m.call_reason : '');

// What happens next depends on whether a person took over
const steps = m.escalated
  ? ['A member of our guest relations team has your case and the full details of your call, so you will not need to repeat yourself.',
     'We will contact you ' + HOTEL.responseTime + ' with an update.',
     'If anything changes in the meantime, simply reply to this email and quote your reference number.']
  : ['Everything discussed on your call has been noted on your booking.',
     'If you need anything else, reply to this email or call us any time.'];
const stepsHtml = steps.map((s, i) =>
  '<tr><td style="vertical-align:top;padding:0 12px 12px 0;width:26px;">' +
  '<div style="width:24px;height:24px;line-height:24px;border-radius:12px;background:' + HOTEL.accent + ';color:#ffffff;font-size:12px;font-weight:700;text-align:center;">' + (i + 1) + '</div></td>' +
  '<td style="vertical-align:top;padding:2px 0 12px;font-size:14px;line-height:1.55;color:#2b2b2b;">' + esc(s) + '</td></tr>').join('');

const preheader = (ticket ? 'Reference ' + ticket + ' · ' : '') + (m.escalated ? 'Our team is on it and will be in touch ' + HOTEL.responseTime + '.' : 'A summary of your call with us.');

const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>' + esc(HOTEL.name) + '</title></head>' +
'<body style="margin:0;padding:0;background:#f3f1ec;">' +
'<div style="display:none;max-height:0;overflow:hidden;opacity:0;">' + esc(preheader) + '</div>' +
'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f3f1ec;"><tr><td align="center" style="padding:32px 12px;">' +
'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Helvetica,Arial,sans-serif;">' +

// header
'<tr><td style="background:' + HOTEL.accent + ';padding:30px 36px 26px;text-align:center;">' +
  '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:24px;letter-spacing:4px;color:#ffffff;">' + esc(HOTEL.name.toUpperCase()) + '</div>' +
  '<div style="width:40px;height:2px;background:' + HOTEL.gold + ';margin:12px auto 10px;"></div>' +
  '<div style="font-size:11px;letter-spacing:3px;color:#cfe3dd;text-transform:uppercase;">' + esc(HOTEL.tagline) + '</div>' +
'</td></tr>' +

// body
'<tr><td style="padding:36px 36px 8px;">' +
  '<p style="margin:0 0 18px;font-family:Georgia,\'Times New Roman\',serif;font-size:20px;color:#1a1a1a;">' + greeting + '</p>' +
  bodyHtml +
'</td></tr>' +

// reference card
(details ? '<tr><td style="padding:4px 36px 8px;">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:' + HOTEL.accentSoft + ';border-radius:10px;border-left:4px solid ' + HOTEL.accent + ';">' +
  '<tr><td style="padding:16px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' + details + '</table></td></tr></table>' +
'</td></tr>' : '') +

// next steps
'<tr><td style="padding:24px 36px 8px;">' +
  '<div style="font-size:12px;letter-spacing:2px;text-transform:uppercase;color:' + HOTEL.gold + ';font-weight:700;margin-bottom:14px;">What happens next</div>' +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0">' + stepsHtml + '</table>' +
'</td></tr>' +

// buttons
'<tr><td style="padding:12px 36px 34px;">' +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>' +
  '<td style="border-radius:8px;background:' + HOTEL.accent + ';"><a href="mailto:' + esc(HOTEL.email) + '?subject=' + encodeURIComponent('Re: ' + (ticket || 'my call')) + '" style="display:inline-block;padding:12px 22px;font-size:14px;font-weight:600;color:#ffffff;text-decoration:none;">Reply to our team</a></td>' +
  '<td style="width:10px;"></td>' +
  '<td style="border-radius:8px;border:1px solid #d6d2c8;"><a href="tel:' + esc(HOTEL.phone.replace(/[^+\d]/g, '')) + '" style="display:inline-block;padding:11px 20px;font-size:14px;font-weight:600;color:' + HOTEL.accent + ';text-decoration:none;">Call ' + esc(HOTEL.phone) + '</a></td>' +
  '</tr></table>' +
'</td></tr>' +

// sign-off
'<tr><td style="padding:0 36px 34px;">' +
  '<p style="margin:0;font-size:15px;line-height:1.6;color:#2b2b2b;">Warm regards,<br><span style="font-family:Georgia,\'Times New Roman\',serif;font-size:17px;color:#1a1a1a;">The ' + esc(HOTEL.name) + ' Guest Care Team</span></p>' +
'</td></tr>' +

// footer
'<tr><td style="background:#faf9f6;border-top:1px solid #ece8df;padding:20px 36px;text-align:center;">' +
  '<p style="margin:0 0 6px;font-size:12px;color:#8a8780;">' + esc(HOTEL.name) + ' · ' + esc(HOTEL.address) + '</p>' +
  '<p style="margin:0;font-size:11px;color:#a5a29b;">You are receiving this email because you called us' + (firstName ? ', ' + esc(firstName) : '') + '. Our AI assistant Aria handled your call and passed the details to our team.</p>' +
'</td></tr>' +

'</table></td></tr></table></body></html>';

const baseSubject = String(m.follow_up_email_subject || ('Following up on your call to ' + HOTEL.name)).trim();
const subject = ticket && !baseSubject.includes(ticket) ? baseSubject + ' · Ref ' + ticket : baseSubject;

return [{ json: { to: m.customer_email, subject, html } }];
